import{_ as e,o,c as a,a3 as r}from"./chunks/framework.Ki30n65y.js";const s="/depgate/screenshots/settings-email.png",u=JSON.parse('{"title":"Email","description":"","frontmatter":{},"headers":[],"relativePath":"admin/email.md","filePath":"admin/email.md"}'),n={name:"admin/email.md"};function i(d,t,l,h,c,p){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="email" tabindex="-1">Email <a class="header-anchor" href="#email" aria-label="Permalink to &quot;Email&quot;">​</a></h1><p>DepGate sends two kinds of email: the <strong>invitation</strong> a new person receives when you add them, and <strong>password reset</strong> links. Both contain single-use links, and people always choose their own password.</p><p>Email is optional. Without it, DepGate shows you the invitation link to send yourself, and <strong>Forgot password?</strong> cannot send mail.</p><h2 id="set-up-smtp" tabindex="-1">Set up SMTP <a class="header-anchor" href="#set-up-smtp" aria-label="Permalink to &quot;Set up SMTP&quot;">​</a></h2><ol><li><p>Go to <strong>Settings → Email</strong>.</p></li><li><p>Fill in your mail server:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>SMTP host</strong></td><td>Your mail server or relay, for example <code>smtp.example.com</code>.</td></tr><tr><td><strong>Port</strong></td><td>Usually <code>587</code> (STARTTLS) or <code>465</code> (TLS).</td></tr><tr><td><strong>Username</strong> and <strong>Password</strong></td><td>If your server requires authentication. The password is stored encrypted and never shown again.</td></tr><tr><td><strong>From address</strong></td><td>The sender, for example <code>DepGate &lt;no-reply@example.com&gt;</code>. Use an address your mail server is allowed to send as.</td></tr><tr><td><strong>Use TLS from the start</strong></td><td>Turn on only for port 465. Port 587 with this off uses STARTTLS.</td></tr></tbody></table></li><li><p>Choose <strong>Save</strong>.</p></li><li><p>Choose <strong>Send test email to me</strong>. DepGate sends a message to your own address and shows the server&#39;s error if it fails.</p></li></ol><p><img src="'+s+'" alt="Email settings"></p><p>You can also set the mail server with environment variables (<code>SMTP_HOST</code>, <code>SMTP_PORT</code>, <code>SMTP_SECURE</code>, <code>SMTP_USER</code>, <code>SMTP_PASSWORD</code>, <code>SMTP_FROM</code>). Settings saved in the web interface take precedence.</p><h2 id="where-the-links-point" tabindex="-1">Where the links point <a class="header-anchor" href="#where-the-links-point" aria-label="Permalink to &quot;Where the links point&quot;">​</a></h2><p>Links in emails start with <code>UI_URL</code> when it is set (it defaults to <code>GATEWAY_URL</code> in the production Compose file). Links are never built from the address in an incoming request, which an attacker could forge.</p><h2 id="link-lifetimes" tabindex="-1">Link lifetimes <a class="header-anchor" href="#link-lifetimes" aria-label="Permalink to &quot;Link lifetimes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Link</th><th>Valid for</th><th>Setting</th></tr></thead><tbody><tr><td>Invitation</td><td>7 days</td><td><code>INVITE_EXPIRY_HOURS</code></td></tr><tr><td>Password reset</td><td>60 minutes</td><td><code>PASSWORD_RESET_EXPIRY_MINUTES</code></td></tr></tbody></table><p>Each link works once.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to check</th></tr></thead><tbody><tr><td>The test email reports <em>connection refused</em></td><td>The host or port is wrong, or a firewall blocks DepGate from reaching the mail server. Email does not use the outbound HTTP proxy.</td></tr><tr><td><strong>Add user</strong> shows a link instead of &quot;invitation sent&quot;</td><td>Email is not set up, or sending failed. The link shown works the same way.</td></tr><tr><td>Links open the wrong address</td><td>Set <code>UI_URL</code> to the address people use.</td></tr><tr><td><strong>Forgot password?</strong> sends nothing</td><td>The address must belong to an existing account. The page answers the same way either way, on purpose.</td></tr></tbody></table><details class="details custom-block"><summary>Testing email without a real mail server</summary><p><a href="https://github.com/axllent/mailpit" target="_blank" rel="noreferrer">Mailpit</a> catches every message and shows it in a web inbox, without delivering anything. Run it with <code>docker run -d -p 1025:1025 -p 8025:8025 axllent/mailpit</code>, set the SMTP host to the machine running it (<code>host.docker.internal</code> when DepGate runs in Docker), port <code>1025</code>, TLS off, and open <a href="http://localhost:8025" target="_blank" rel="noreferrer">http://localhost:8025</a> to read the messages.</p></details>',15)])])}const g=e(n,[["render",i]]);export{u as __pageData,g as default};
